import (
	"context"
	"fmt"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/git"
)

// assertStagedIsExactly checks the index just before a commit is made from it.
//
// Every caller in this package stages a named list of paths and never `add -A`,
// which is what lets a deployment commit be read as a statement about one
// component. That property is worth verifying rather than assuming: the checkout
// is shared, git runs code the repository supplies while building a commit, and
// the difference between what was asked for and what was recorded is one command
// away.
func assertStagedIsExactly(ctx context.Context, g git.Client, expected []string) error {
	staged, err := g.StagedPaths(ctx)
	if err != nil {
		return err
	}
	return assertOnly("staged", expected, staged)
}

// assertCommittedIsExactly checks HEAD, which is the last moment before a push
// makes it everyone's.
//
// Both halves are checked because they answer different questions: the index is
// what the commit is about to be made from, and this is what a push would publish,
// with a hook's opportunity to run in between. It has to be a second call rather
// than a replacement — once the commit exists the index matches HEAD and has
// nothing left to report.
func assertCommittedIsExactly(ctx context.Context, g git.Client, expected []string) error {
	head, err := g.HEAD(ctx)
	if err != nil {
		return err
	}
	committed, err := g.CommitPaths(ctx, head)
	if err != nil {
		return err
	}
	return assertOnly("committed", expected, committed)
}

// assertOnly refuses anything git recorded that was not asked for.
//
// A subset rather than an equality: a file whose content already matches is
// staged and changes nothing, so a shorter list than expected is normal. A longer
// one is not, and there is no benign explanation for it.
func assertOnly(what string, expected, actual []string) error {
	var extra []string
	for _, p := range actual {
		if !slices.Contains(expected, p) {
			extra = append(extra, p)
		}
	}
	if len(extra) == 0 {
		return nil
	}
	slices.Sort(extra)
	return fmt.Errorf("refusing to continue: %d path%s %s that this command did not ask for:\n  %s\n\nNothing has been pushed. A git hook or another process is writing into the cached checkout",
		len(extra), plural(len(extra)), what, strings.Join(extra, "\n  "))
}
package deploy

import (
	"context"
	"fmt"
	"io"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// session is the state every command in this package starts from: a refreshed
// GitOps checkout and the repository-level policy in it.
type session struct {
	repo      *gitops.Repository
	deployCfg *gitops.DeployConfig

	// argocdServer is argocdServer from the user's configuration file, the last
	// resort when neither the flag nor deploy.yaml names one.
	argocdServer string
}

// sessionOptions is the subset of a command's options openSession needs.
type sessionOptions struct {
	GitopsRepo   string
	ArgocdServer string
	CacheRoot    string
	Runner       command.Runner
	Stderr       io.Writer
}

// openSession resolves the GitOps repository, refreshes the cached checkout and
// loads deploy.yaml.
//
// binaries are required up front, before any network or cache work: discovering
// a missing kustomize after cloning wastes the user's time. Which ones is the
// caller's business — sync renders nothing, so demanding kustomize of it would
// be a prerequisite it never uses.
//
// The caller owns the returned repository and must Close it.
func openSession(ctx context.Context, opts sessionOptions, binaries ...string) (*session, error) {
	if err := command.RequireBinaries(binaries...); err != nil {
		return nil, err
	}

	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo, ArgocdServer: opts.ArgocdServer})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return nil, err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot, Stderr: opts.Stderr})
	if err != nil {
		return nil, err
	}
	// Open has already refused a push address that is a different repository, so
	// anything left is the same repository under another name — an insteadOf
	// rewrite. Worth showing: the address a deployment leaves for is not something
	// to discover afterwards.
	if repo.PushURL != "" && repo.PushURL != repoURL {
		fmt.Fprintf(opts.Stderr, "note: git pushes %s as %s\n", repoURL, repo.PushURL)
	}

	deployCfg, err := gitops.LoadDeployConfig(repo.Root)
	if err != nil {
		repo.Close()
		return nil, err
	}

	return &session{repo: repo, deployCfg: deployCfg, argocdServer: resolved.ArgocdServer}, nil
}

func (s *session) Close() { s.repo.Close() }

// locateComponent finds the component in the GitOps tree and reads its
// component.yaml. domain and system disambiguate a name that occurs more than
// once.
func (s *session) locateComponent(component, domain, system string) (gitops.Coordinate, *gitops.ComponentConfig, error) {
	coord, err := gitops.FindComponent(s.repo.Root, component, domain, system)
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	comp, err := gitops.LoadComponentConfig(componentDir(s.repo.Root, coord))
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	return coord, comp, nil
}

// componentKind is the component's kind with the default made explicit, so a
// reported value never depends on whether component.yaml spelled it out.
func componentKind(comp *gitops.ComponentConfig) string {
	if comp.Kind == "" {
		return gitops.KindService
	}
	return comp.Kind
}

// requirePinnable rejects a component that has no image to pin.
//
// deploy and promote exist to move image digests, so a shared component is a
// category error for them rather than a run that happens to change nothing —
// without this the plan would come out empty and read as "already up to date".
// status, diff and sync all work on a shared component and must not call this.
func requirePinnable(coord gitops.Coordinate, comp *gitops.ComponentConfig) error {
	if !comp.IsShared() {
		return nil
	}
	return fmt.Errorf("%s is kind %q; it declares no images, so there is nothing to pin — edit its manifests directly", coord, gitops.KindShared)
}

// Package git wraps the git binary with the operations the deployment
// commands need. It is deliberately narrow: only what is used, and nothing
// that would tempt a caller into arbitrary git.
package git

import (
	"context"
	"errors"
	"fmt"
	"os"
	"slices"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

// Client is a typed wrapper over the git binary rooted at a working directory.
//
// A zero Client works on a repository the user owns, where git behaves exactly as
// they configured it. NewManagedClient is for the checkouts this CLI creates and
// is the sole writer of.
type Client struct {
	Runner command.Runner
	Dir    string

	// managed marks a checkout this CLI created and owns. Unexported and settable
	// only through NewManagedClient, because the default has to be the user's own
	// repository: reinterpreting how git behaves there is not this package's call.
	managed bool
}

// NewManagedClient returns a client for a checkout this CLI created, owns and is
// the only writer of — today, the cached GitOps clone.
//
// Only these are hardened. The distinction is not cosmetic: a user's own
// repository is theirs, their hooks are their policy, and a release tag pushed
// from their source tree must go through the same pre-push checks any other push
// of theirs would. The cached clone is the opposite case — nobody configured it,
// nobody reviews what lands in it, and this CLI is the only thing that commits
// there.
func NewManagedClient(r command.Runner, dir string) Client {
	return Client{Runner: r, Dir: dir, managed: true}
}

// hardening is prepended to every invocation on a managed checkout.
//
// A commit there is built from an exact list of paths, and the callers say so:
// nothing is staged implicitly, and never `add -A`. Ambient configuration can
// defeat that on its own, because a hook is code the repository supplies and git
// runs it while building the commit — a pre-commit hook can stage anything it
// likes, and the result is pushed to the GitOps repository's default branch as if
// this CLI had asked for it. core.hooksPath is the one setting that disables every
// hook at once, including the ones no --no-verify flag covers (post-checkout,
// post-rewrite during a rebase, reference-transaction), and -c beats the
// repository, global and system configuration it could be set in.
//
// Signing is deliberately left alone: an organisation whose remote requires
// signed commits would have every push rejected, and signing was never how a
// commit acquires files it should not contain.
var hardening = []string{
	// A directory that cannot contain a hook, because it is not a directory.
	"-c", "core.hooksPath=" + os.DevNull,

	// A filesystem monitor is a long-lived helper process started on demand; the
	// deployment commands touch a handful of files in a cache and have no use for
	// one.
	"-c", "core.fsmonitor=false",
}

// NonInteractiveEnv is the environment git needs when its output is captured.
//
// Without it git prompts for credentials on /dev/tty, which is still there even
// though this package gives the child no stdin and reads its output into a
// buffer — so a missing credential reads as a hang with no explanation. With it,
// the same situation is an error that says what happened. Credential helpers and
// SSH agents keep working: only the fallback to asking a human is removed.
func NonInteractiveEnv() []string {
	return []string{"GIT_TERMINAL_PROMPT=0"}
}

// DefaultRunner is the runner every git call site should default to.
func DefaultRunner() command.Runner {
	return command.ExecRunner{Env: NonInteractiveEnv()}
}

func (g Client) run(ctx context.Context, args ...string) (string, error) {
	if g.managed {
		// Concat rather than append: appending to a package-level slice would let
		// two concurrent calls share its backing array.
		args = slices.Concat(hardening, args)
	}
	stdout, _, err := g.Runner.Run(ctx, g.Dir, "git", args...)
	return strings.TrimSpace(string(stdout)), err
}

// HEAD returns the full commit sha of HEAD. Full, not abbreviated: an
// abbreviated sha is ambiguous as a registry tag and as an ancestry argument.
func (g Client) HEAD(ctx context.Context) (string, error) {
	sha, err := g.run(ctx, "rev-parse", "HEAD")
	if err != nil {
		return "", fmt.Errorf("resolve HEAD: %w", err)
	}
	return sha, nil
}

// Status returns porcelain status lines limited to paths, or to the whole tree
// when no paths are given.
//
// Untracked files are listed individually rather than collapsed to their
// directory: these lines are shown to the user when a deploy is refused, and
// "component/" is a much less useful answer than the files that are actually
// uncommitted.
func (g Client) Status(ctx context.Context, paths ...string) ([]string, error) {
	args := []string{"status", "--porcelain", "--untracked-files=all"}
	if len(paths) > 0 {
		args = append(args, "--")
		args = append(args, paths...)
	}
	out, err := g.run(ctx, args...)
	if err != nil {
		return nil, fmt.Errorf("read working tree status: %w", err)
	}
	if out == "" {
		return nil, nil
	}
	return strings.Split(out, "\n"), nil
}

// Fetch updates remote-tracking refs. Callers that are about to reason about
// ancestry must fetch first: a stale origin/<branch> makes a pushed commit look
// unpushed.
func (g Client) Fetch(ctx context.Context, remote string, refspecs ...string) error {
	args := append([]string{"fetch", "--quiet", remote}, refspecs...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("fetch %s: %w", remote, err)
	}
	return nil
}

// DefaultBranch returns the remote's default branch name, preferring the
// symbolic ref that git records at clone time and falling back to querying the
// remote. Hardcoding "main" would be wrong for any repository that never
// renamed from master.
func (g Client) DefaultBranch(ctx context.Context, remote string) (string, error) {
	if out, err := g.run(ctx, "symbolic-ref", "--short", "refs/remotes/"+remote+"/HEAD"); err == nil {
		// refs/remotes/origin/HEAD reads back as "origin/main".
		if _, branch, ok := strings.Cut(out, "/"); ok && branch != "" {
			return branch, nil
		}
	}

	// Freshly cloned mirrors and worktrees created with --single-branch may
	// have no origin/HEAD; ask the remote directly.
	out, err := g.run(ctx, "ls-remote", "--symref", remote, "HEAD")
	if err != nil {
		return "", fmt.Errorf("determine default branch of %s: %w", remote, err)
	}
	for line := range strings.SplitSeq(out, "\n") {
		// "ref: refs/heads/main\tHEAD"
		rest, ok := strings.CutPrefix(strings.TrimSpace(line), "ref: refs/heads/")
		if !ok {
			continue
		}
		if branch, _, _ := strings.Cut(rest, "\t"); branch != "" {
			return branch, nil
		}
	}
	return "", fmt.Errorf("determine default branch of %s: no symref in ls-remote output", remote)
}

// RemoteURL returns the URL configured for remote, and whether it is configured
// at all.
//
// This is the identity of the checkout, and the only way to tell whether a
// cached clone is a clone of the repository the caller asked for: a directory
// name says what it was created for, not what its git config now points at.
func (g Client) RemoteURL(ctx context.Context, remote string) (string, bool, error) {
	url, err := g.run(ctx, "config", "--get", "remote."+remote+".url")
	if err == nil {
		return url, url != "", nil
	}
	// git exits 1 when the key is simply not set, which is an answer rather than
	// a failure to read it.
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return "", false, nil
	}
	return "", false, fmt.Errorf("read the URL of %s: %w", remote, err)
}

// PushURL returns the URL a push to remote would actually reach, with pushurl and
// url.<base>.pushInsteadOf rewrites applied.
//
// remote.<remote>.url is where a fetch comes from, and it is not where a push
// goes. Any caller that has verified the one and not the other has verified
// nothing about where its commits end up.
func (g Client) PushURL(ctx context.Context, remote string) (string, error) {
	url, err := g.run(ctx, "remote", "get-url", "--push", remote)
	if err != nil {
		return "", fmt.Errorf("resolve the push URL of %s: %w", remote, err)
	}
	return url, nil
}

// RemotePushURL returns the pushurl configured for remote in this repository, and
// whether one is configured at all.
//
// Distinct from PushURL: this reads one key, rather than the address git would
// arrive at after every rewrite rule in every configuration file has had its say.
func (g Client) RemotePushURL(ctx context.Context, remote string) (string, bool, error) {
	url, err := g.run(ctx, "config", "--get", "remote."+remote+".pushurl")
	if err == nil {
		return url, url != "", nil
	}
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return "", false, nil
	}
	return "", false, fmt.Errorf("read the pushurl of %s: %w", remote, err)
}

// ClearRemotePushURL removes every pushurl configured for remote in this
// repository's own configuration.
//
// Only call it for a key that exists: git exits 5 for unsetting one that does not.
func (g Client) ClearRemotePushURL(ctx context.Context, remote string) error {
	if _, err := g.run(ctx, "config", "--unset-all", "remote."+remote+".pushurl"); err != nil {
		return fmt.Errorf("remove the pushurl of %s: %w", remote, err)
	}
	return nil
}

// IsAncestor reports whether ancestor is an ancestor of descendant. Equal
// commits count as ancestors, matching git's own semantics.
func (g Client) IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error) {
	_, err := g.run(ctx, "merge-base", "--is-ancestor", ancestor, descendant)
	if err == nil {
		return true, nil
	}
	// git exits 1 for "not an ancestor" and 128 for a bad revision, so only
	// exit 1 may be read as a clean negative answer.
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return false, nil
	}
	return false, fmt.Errorf("check whether %s is an ancestor of %s: %w", ShortSHA(ancestor), ShortSHA(descendant), err)
}

// Add stages paths.
func (g Client) Add(ctx context.Context, paths ...string) error {
	args := append([]string{"add", "--"}, paths...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("stage changes: %w", err)
	}
	return nil
}

// StagedPaths lists the paths the index changes relative to HEAD, repository-root
// relative and slash-separated.
//
// This is how a caller checks that staging an exact list of paths produced exactly
// that index, rather than assuming it did.
func (g Client) StagedPaths(ctx context.Context) ([]string, error) {
	out, err := g.run(ctx, "diff", "--cached", "--name-only", "--no-renames", "-z")
	if err != nil {
		return nil, fmt.Errorf("read the staged paths: %w", err)
	}
	return splitNUL(out), nil
}

// CommitPaths lists the paths a commit changed relative to its parent.
//
// StagedPaths answers what was about to be committed; this answers what was, which
// is the last chance to notice a difference before a push makes it everyone's.
func (g Client) CommitPaths(ctx context.Context, rev string) ([]string, error) {
	// --root so a repository's first commit reports its files rather than nothing.
	out, err := g.run(ctx, "diff-tree", "-r", "--root", "--no-commit-id", "--name-only", "--no-renames", "-z", rev)
	if err != nil {
		return nil, fmt.Errorf("read the paths changed by %s: %w", ShortSHA(rev), err)
	}
	return splitNUL(out), nil
}

// splitNUL splits git's -z output. NUL-terminated records are the only form in
// which git never quotes or escapes a path, which matters because these paths are
// compared against ones this CLI produced.
func splitNUL(out string) []string {
	var paths []string
	for p := range strings.SplitSeq(out, "\x00") {
		if p != "" {
			paths = append(paths, p)
		}
	}
	return paths
}

// CheckoutPaths discards working-tree changes under paths. Always pass an
// explicit path: an unscoped revert would throw away anything else in the
// worktree, including a concurrent run's staged work.
func (g Client) CheckoutPaths(ctx context.Context, paths ...string) error {
	if len(paths) == 0 {
		return errors.New("CheckoutPaths requires at least one path")
	}
	args := append([]string{"checkout", "--"}, paths...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("discard changes: %w", err)
	}
	return nil
}

// CreateBranch creates name at startPoint and checks it out, resetting it if it
// already exists locally.
//
// The reset is deliberate: the only local branches in a cached checkout are ones
// a previous run of this CLI left behind, and reusing a stale one would build a
// commit on top of whatever that run happened to do.
func (g Client) CreateBranch(ctx context.Context, name, startPoint string) error {
	if _, err := g.run(ctx, "checkout", "-B", name, startPoint); err != nil {
		return fmt.Errorf("create branch %s at %s: %w", name, startPoint, err)
	}
	return nil
}

// Switch checks out an existing ref.
//
// Callers holding a shared cached checkout must switch back to the default
// branch when they are done: the refresh on the next Open resets whatever branch
// is current to the default branch's remote head, which would silently discard a
// feature branch's commits.
func (g Client) Switch(ctx context.Context, ref string) error {
	if _, err := g.run(ctx, "checkout", ref); err != nil {
		return fmt.Errorf("switch to %s: %w", ref, err)
	}
	return nil
}

// ResetHard moves the branch and working tree to ref.
func (g Client) ResetHard(ctx context.Context, ref string) error {
	if _, err := g.run(ctx, "reset", "--hard", ref); err != nil {
		return fmt.Errorf("reset to %s: %w", ref, err)
	}
	return nil
}

// Clean removes untracked files and directories.
func (g Client) Clean(ctx context.Context) error {
	if _, err := g.run(ctx, "clean", "-fdq"); err != nil {
		return fmt.Errorf("clean working tree: %w", err)
	}
	return nil
}

// RevParse resolves any revision expression to a full sha.
func (g Client) RevParse(ctx context.Context, rev string) (string, error) {
	sha, err := g.run(ctx, "rev-parse", rev)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", rev, err)
	}
	return sha, nil
}

// Clone clones url into dir. dir must not already exist.
func Clone(ctx context.Context, r command.Runner, url, dir string) error {
	return clone(ctx, r, url, dir, nil)
}

// CloneManaged clones into a directory this CLI will own, with hooks disabled for
// the same reason NewManagedClient disables them: a clone checks out a worktree,
// which runs post-checkout — the first opportunity a repository has to run code of
// its own in a checkout we are about to commit in.
func CloneManaged(ctx context.Context, r command.Runner, url, dir string) error {
	return clone(ctx, r, url, dir, hardening)
}

func clone(ctx context.Context, r command.Runner, url, dir string, prefix []string) error {
	args := slices.Concat(prefix, []string{"clone", "--quiet", url, dir})
	if _, _, err := r.Run(ctx, "", "git", args...); err != nil {
		return fmt.Errorf("clone %s: %w", url, err)
	}
	return nil
}

// ShortSHA abbreviates a sha for messages, leaving non-sha revisions alone.
func ShortSHA(rev string) string {
	if len(rev) >= 40 {
		return rev[:7]
	}
	return rev
}

// Commit records the staged changes. Each message becomes a paragraph, which is
// how a subject line and a trailer block are produced without a temporary file:
// git separates -m arguments with a blank line, and trailers only need to be
// the final paragraph to be parseable by `git log --format=%(trailers)`.
//
// Nothing is staged implicitly — there is no -a — so the caller decides exactly
// what the commit contains. On a managed checkout --no-verify is belt and braces
// on top of the core.hooksPath in hardening: the two disable hooks by different
// mechanisms, and this is the operation where a hook would do the most damage.
func (g Client) Commit(ctx context.Context, messages ...string) error {
	if len(messages) == 0 {
		return errors.New("Commit requires at least a subject")
	}
	args := []string{"commit", "--quiet"}
	if g.managed {
		args = append(args, "--no-verify")
	}
	for _, m := range messages {
		args = append(args, "-m", m)
	}
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Tag creates an annotated tag at commit. Annotated rather than lightweight:
// it carries the author, date and message that make the tag worth reading in
// `git log`, which is the only reason the tag exists.
//
// Creating a tag that already exists is an error rather than a silent move —
// a release tag that quietly relocates would misrepresent history.
func (g Client) Tag(ctx context.Context, name, message, commit string) error {
	if _, err := g.run(ctx, "tag", "--annotate", "--message", message, name, commit); err != nil {
		return fmt.Errorf("tag %s: %w", name, err)
	}
	return nil
}

// TagCommit resolves an annotated or lightweight tag to the commit it points
// at. The bool reports whether the tag exists locally at all, so a caller can
// tell "no such tag" from a genuine failure to read it.
func (g Client) TagCommit(ctx context.Context, name string) (string, bool, error) {
	// ^{commit} dereferences an annotated tag to its commit; without it the
	// answer would be the tag object's own sha, which never matches a commit.
	sha, err := g.run(ctx, "rev-parse", "--verify", "--quiet", "refs/tags/"+name+"^{commit}")
	if err == nil {
		return sha, sha != "", nil
	}
	// --quiet makes an unknown ref exit 1 with no output, which is the answer
	// rather than a failure.
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return "", false, nil
	}
	return "", false, fmt.Errorf("resolve tag %s: %w", name, err)
}

// LogCommit is one commit in a range, reduced to what release notes need.
type LogCommit struct {
	SHA     string
	Subject string
}

// LastCommit returns the sha of the most recent commit on rev that changed path,
// and whether there was one.
//
// Merges are not excluded here, unlike Log: this answers "which commit put the
// file in its current state", and a merge that resolved the file really is that
// commit.
func (g Client) LastCommit(ctx context.Context, rev, path string) (string, bool, error) {
	sha, _, found, err := g.LastCommitAt(ctx, rev, path)
	return sha, found, err
}

// LastCommitAt is LastCommit with the commit's timestamp, which is what dates a
// deployment: an overlay changed when the commit that changed it landed.
//
// The committer date rather than the author date. Publish rebases and retries
// when the push races another deployment, which rewrites the committer date and
// leaves the author date at the first attempt; the later of the two is when the
// change actually reached the branch.
func (g Client) LastCommitAt(ctx context.Context, rev, path string) (string, time.Time, bool, error) {
	// NUL-separated for the same reason Log is: the fields are fixed-width here,
	// but one delimiter convention in this file is one fewer thing to get wrong.
	out, err := g.run(ctx, "log", "-1", "--format=%H%x00%cI", rev, "--", path)
	if err != nil {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: %w", path, err)
	}
	if out == "" {
		return "", time.Time{}, false, nil
	}

	sha, date, ok := strings.Cut(out, "\x00")
	if !ok {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: unexpected git log output %q", path, out)
	}
	at, err := time.Parse(time.RFC3339, date)
	if err != nil {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: parse commit date %q: %w", path, date, err)
	}
	return sha, at, true, nil
}

// Log lists the commits in revRange, most recent first, limited to paths when
// any are given.
//
// The two fields are separated by a NUL and the records by a newline: a commit
// subject may contain anything except a newline, so a printable delimiter
// could appear inside one and split a record in the wrong place.
func (g Client) Log(ctx context.Context, revRange string, paths ...string) ([]LogCommit, error) {
	args := []string{"log", "--format=%H%x00%s", "--no-merges", revRange}
	if len(paths) > 0 {
		args = append(args, "--")
		args = append(args, paths...)
	}
	out, err := g.run(ctx, args...)
	if err != nil {
		return nil, fmt.Errorf("read log for %s: %w", revRange, err)
	}
	if out == "" {
		return nil, nil
	}

	var commits []LogCommit
	for line := range strings.SplitSeq(out, "\n") {
		sha, subject, ok := strings.Cut(line, "\x00")
		if !ok {
			continue
		}
		commits = append(commits, LogCommit{SHA: sha, Subject: subject})
	}
	return commits, nil
}

// Push pushes refspec to remote.
//
// A rejection is reported as *PushRejectedError so callers can rebase and retry,
// distinguished from an authentication or network failure where retrying is
// pointless.
//
// A push from a repository the user owns runs their pre-push hook, whatever it is.
// That is their policy — a release tag leaving their source tree must clear the
// same checks any other push of theirs would.
func (g Client) Push(ctx context.Context, remote, refspec string) error {
	args := []string{"push", "--quiet"}
	if g.managed {
		args = append(args, "--no-verify")
	}
	args = append(args, remote, refspec)
	_, err := g.run(ctx, args...)
	if err == nil {
		return nil
	}
	if ee, ok := errors.AsType[*command.ExitError](err); ok && isRejection(ee.Stderr) {
		return &PushRejectedError{Remote: remote, Refspec: refspec, Stderr: ee.Stderr}
	}
	return fmt.Errorf("push %s %s: %w", remote, refspec, err)
}

// PushRejectedError reports that the remote refused the push because it has
// commits we do not have.
type PushRejectedError struct {
	Remote  string
	Refspec string
	Stderr  string
}

func (e *PushRejectedError) Error() string {
	return fmt.Sprintf("push to %s was rejected: %s", e.Remote, strings.TrimSpace(e.Stderr))
}

// isRejection recognises a non-fast-forward refusal. git has no distinct exit
// code for it, so the message is the only signal available; the phrases below
// are the ones git itself emits.
func isRejection(stderr string) bool {
	for _, marker := range []string{"[rejected]", "non-fast-forward", "fetch first", "Updates were rejected"} {
		if strings.Contains(stderr, marker) {
			return true
		}
	}
	return false
}

// Rebase replays the current branch onto upstream.
//
// A conflict is reported as *RebaseConflictError with the rebase left in
// progress, so the caller can decide — this package must not abort on the
// caller's behalf, because whether a conflict is recoverable is policy.
func (g Client) Rebase(ctx context.Context, upstream string) error {
	_, err := g.run(ctx, "rebase", upstream)
	if err == nil {
		return nil
	}
	if ee, ok := errors.AsType[*command.ExitError](err); ok {
		return &RebaseConflictError{Upstream: upstream, Stderr: ee.Stderr}
	}
	return fmt.Errorf("rebase onto %s: %w", upstream, err)
}

// RebaseConflictError reports a rebase that stopped, leaving the repository
// mid-rebase.
type RebaseConflictError struct {
	Upstream string
	Stderr   string
}

func (e *RebaseConflictError) Error() string {
	return fmt.Sprintf("rebase onto %s stopped: %s", e.Upstream, strings.TrimSpace(e.Stderr))
}

// RebaseAbort restores the state from before a rebase.
func (g Client) RebaseAbort(ctx context.Context) error {
	if _, err := g.run(ctx, "rebase", "--abort"); err != nil {
		return fmt.Errorf("abort rebase: %w", err)
	}
	return nil
}

// Trailers returns the trailer block of a commit message as ordered pairs.
// Duplicate keys are preserved, since a commit may legitimately repeat one.
func (g Client) Trailers(ctx context.Context, rev string) ([]Trailer, error) {
	out, err := g.run(ctx, "log", "-1", "--format=%(trailers:only=true)", rev)
	if err != nil {
		return nil, fmt.Errorf("read trailers of %s: %w", ShortSHA(rev), err)
	}
	var trailers []Trailer
	for line := range strings.SplitSeq(out, "\n") {
		key, value, ok := strings.Cut(strings.TrimSpace(line), ":")
		if !ok || key == "" {
			continue
		}
		trailers = append(trailers, Trailer{Key: key, Value: strings.TrimSpace(value)})
// Package gitops models the GitOps repository: a cached, locked checkout of
// it, the directory layout that locates a component, and the two contract
// files (deploy.yaml and component.yaml) that describe what may be deployed
// where.
package gitops

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
)

// Repository is a local clone of a GitOps repository, cached between runs and
// held under an exclusive lock for the duration of one.
type Repository struct {
	// Root is the checkout directory.
	Root string

	// URL is the remote this was cloned from.
	URL string

	// PushURL is where a push actually goes, with any pushurl or
	// url.<base>.pushInsteadOf rewrite applied. Open verifies that it identifies
	// the same repository as URL and fails otherwise, so this is never a surprise
	// by the time a caller holds it — only a possibly different spelling, which is
	// worth showing the user.
	PushURL string

	// Branch is the remote's default branch, the branch deploys land on.
	Branch string

	Git git.Client

	lock *os.File
}

// RemoteName is the remote deploys read from and push to.
const RemoteName = "origin"

// Options configures Open.
type Options struct {
	// URL is the GitOps repository to clone. Required.
	URL string

	// Runner runs git. Defaults to git.DefaultRunner.
	Runner command.Runner

	// CacheRoot overrides where checkouts are cached. Defaults to
	// <user cache dir>/intropy/gitops. Injectable so tests can redirect the
	// cache without reaching for HOME — on macOS os.UserCacheDir derives from
	// it, and overriding HOME makes every git invocation pay a multi-second
	// penalty for a home directory that does not match the passwd entry.
	CacheRoot string

	// Stderr receives notes about the cache itself, such as a checkout being
	// re-cloned. Defaults to io.Discard.
	Stderr io.Writer
}

// Open returns a clean, up-to-date checkout of the GitOps repository.
//
// The checkout is cached and reused across runs, so a deploy does not pay for a
// full clone every time. Because it is shared, four things are non-negotiable: an
// exclusive lock for the whole run, a verified origin, a hard reset rather than a
// merge on refresh, and removal of untracked files. A previous run killed part-way
// through an edit must not be able to leak that edit into this one's commit.
//
// The caller must Close the result.
func Open(ctx context.Context, opts Options) (*Repository, error) {
	if opts.URL == "" {
		return nil, errors.New("no GitOps repository URL")
	}
	r := opts.Runner
	if r == nil {
		r = git.DefaultRunner()
	}
	stderr := opts.Stderr
	if stderr == nil {
		stderr = io.Discard
	}
	url := opts.URL

	cacheRoot := opts.CacheRoot
	if cacheRoot == "" {
		var err error
		if cacheRoot, err = defaultCacheRoot(); err != nil {
			return nil, err
		}
	}
	dir := CheckoutDir(cacheRoot, url)
	if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
		return nil, fmt.Errorf("create cache directory: %w", err)
	}

	lock, err := acquireLock(dir + ".lock")
	if err != nil {
		return nil, err
	}

	wt := &Repository{Root: dir, URL: url, lock: lock}
	// Managed: this directory is the CLI's own, nobody configured it, and nothing
	// but this CLI commits there.
	wt.Git = git.NewManagedClient(r, dir)

	if err := wt.refresh(ctx, r, stderr); err != nil {
		wt.Close()
		return nil, err
	}
	return wt, nil
}

func (w *Repository) refresh(ctx context.Context, r command.Runner, stderr io.Writer) error {
	if err := w.ensureCheckout(ctx, r, stderr); err != nil {
		return err
	}

	if err := w.ensurePushDestination(ctx, stderr); err != nil {
		return err
	}

	branch, err := w.Git.DefaultBranch(ctx, RemoteName)
	if err != nil {
		return err
	}
	w.Branch = branch

	if err := w.Git.Fetch(ctx, RemoteName, branch); err != nil {
		return err
	}
	// Hard reset, not pull: the cache has no local history worth preserving,
	// and a merge could leave conflict markers in a file we are about to
	// commit.
	if err := w.Git.ResetHard(ctx, RemoteName+"/"+branch); err != nil {
		return err
	}
	return w.Git.Clean(ctx)
}

// ensureCheckout leaves w.Root holding a clone of w.URL and nothing else.
//
// The cache directory is named after a hash of the URL, which records what it was
// created for — not what its git config points at now. Nothing stops that config
// from being stale, half-written by an interrupted run, or edited, and every later
// step trusts "origin": the fetch that decides what is deployed and the push that
// publishes it. So the origin is read back and checked, every time.
//
// A mismatch re-clones rather than failing. This directory is a cache and holds
// nothing worth keeping — the refresh below resets and cleans it on every open
// anyway — so recovering is both safe and the only outcome the user wanted.
func (w *Repository) ensureCheckout(ctx context.Context, r command.Runner, stderr io.Writer) error {
	_, err := os.Stat(filepath.Join(w.Root, ".git"))
	switch {
	case err == nil:
		have, ok, err := w.Git.RemoteURL(ctx, RemoteName)
		if err != nil {
			return err
		}
		if ok && SameRepository(have, w.URL) {
			return nil
		}
		if ok {
			fmt.Fprintf(stderr, "the cached checkout in %s has %s as %s, not %s; re-cloning\n", w.Root, have, RemoteName, w.URL)
		} else {
			fmt.Fprintf(stderr, "the cached checkout in %s has no %s remote; re-cloning\n", w.Root, RemoteName)
		}
	case errors.Is(err, fs.ErrNotExist):
		// A directory without .git is the debris of an interrupted clone;
		// git clone refuses to write into it, so clear it first.
	default:
		return fmt.Errorf("inspect %s: %w", w.Root, err)
	}

	if err := os.RemoveAll(w.Root); err != nil {
		return fmt.Errorf("clear %s: %w", w.Root, err)
	}
	if err := git.CloneManaged(ctx, r, w.URL, w.Root); err != nil {
		return err
	}

	// Read back what the clone recorded. A clone that did not end up pointing at
	// the requested repository must not go on to fetch or push.
	have, ok, err := w.Git.RemoteURL(ctx, RemoteName)
	if err != nil {
		return err
	}
	if !ok || !SameRepository(have, w.URL) {
		return fmt.Errorf("cloned %s into %s but its %s is %q", w.URL, w.Root, RemoteName, have)
	}
	return nil
}

// ensurePushDestination makes the address a push will actually reach be the
// repository the caller asked for.
//
// A verified remote.origin.url is only half the answer. git pushes to
// remote.origin.pushurl when one is set, and url.<base>.pushInsteadOf rewrites the
// address on the way out; either can send a deployment to a repository nobody
// named. Reporting that is no defence — by the time anyone reads a warning the
// commit has already landed somewhere else — so this fails closed, before any
// command in this CLI has done work it would have to throw away.
//
// A pushurl in this repository's own config is removed rather than refused. This
// CLI never sets one, so in a directory it owns that key is debris or tampering
// either way, and clearing it is the same self-healing ensureCheckout does. A
// rewrite rule is not removed: it can come from configuration this CLI has no
// business editing, and the honest answer there is to stop.
func (w *Repository) ensurePushDestination(ctx context.Context, stderr io.Writer) error {
	local, ok, err := w.Git.RemotePushURL(ctx, RemoteName)
	if err != nil {
		return err
	}
	if ok {
		fmt.Fprintf(stderr, "the cached checkout in %s sets a push address of its own for %s (%s); removing it\n", w.Root, RemoteName, local)
		if err := w.Git.ClearRemotePushURL(ctx, RemoteName); err != nil {
			return err
		}
	}

	// Resolved after the removal, so this is the address that would be used now.
	pushURL, err := w.Git.PushURL(ctx, RemoteName)
	if err != nil {
		return err
	}
	if !SameRepository(pushURL, w.URL) {
		return fmt.Errorf("git would push %s to %s, which is a different repository.\n"+
			"A pushurl or a url.<base>.pushInsteadOf rule in your git configuration redirects it. Nothing has been pushed.\n"+
			"If the redirect is intentional, configure gitopsRepo as the repository you actually deploy to; otherwise remove the rule",
			w.URL, pushURL)
	}
	w.PushURL = pushURL
	return nil
}

// Close releases the lock. The checkout itself is deliberately kept.
func (w *Repository) Close() error {
	if w.lock == nil {
		return nil
	}
	err := syscall.Flock(int(w.lock.Fd()), syscall.LOCK_UN)
	if cerr := w.lock.Close(); err == nil {
		err = cerr
	}
	w.lock = nil
	return err
}

func defaultCacheRoot() (string, error) {
	base, err := os.UserCacheDir()
	if err != nil {
		return "", fmt.Errorf("locate cache directory: %w", err)
	}
	return filepath.Join(base, "intropy", "gitops"), nil
}

// CachedRoot returns the existing cached checkout for the configured GitOps
// repository.
//
// It never clones or fetches. This backs shell completion, which has to be
// instant and must not touch the network — an unconfigured or not-yet-cloned
// repository simply yields no suggestions.
func CachedRoot(gitopsRepoOverride string) (string, error) {
	cfg, err := config.Load()
	if err != nil {
		return "", err
	}
	url, err := cfg.Resolve(config.Flags{GitopsRepo: gitopsRepoOverride}).RequireGitopsRepo()
	if err != nil {
		return "", err
	}
	cacheRoot, err := defaultCacheRoot()
	if err != nil {
		return "", err
	}
	dir := CheckoutDir(cacheRoot, url)
	if _, err := os.Stat(filepath.Join(dir, ".git")); err != nil {
		return "", fmt.Errorf("no cached checkout of %s yet", url)
	}
	return dir, nil
}

// CheckoutDir derives a stable cache path from the remote URL. The URL is
// hashed rather than sanitised because the same repository can be named several
// ways (SSH, HTTPS, with or without .git) and because URLs contain characters
// that are awkward in paths.
func CheckoutDir(cacheRoot, url string) string {
	sum := sha256.Sum256([]byte(url))
	return filepath.Join(cacheRoot, hex.EncodeToString(sum[:])[:16])
}

package gitops

import (
	"net/url"
	"strings"
)

// SameRepository reports whether two remote URLs name the same repository.
//
// One repository has many spellings — SSH and HTTPS, scp-form and ssh://, with
// and without .git, with and without a trailing slash — and a cached checkout's
// origin is compared against a URL a human typed into config.yaml. Comparing the
// strings would re-clone the cache on a cosmetic difference.
//
// Deliberately not used to derive the cache directory: CheckoutDir hashes the URL
// exactly as given, so the two spellings get two caches. That is a wasted clone
// at worst, whereas treating two repositories as one would be a deploy to the
// wrong place. This function only ever decides "is this cache still ours".
func SameRepository(a, b string) bool {
	return normalizeRepoURL(a) == normalizeRepoURL(b)
}

// normalizeRepoURL reduces a remote URL to host, port and path.
//
// Credentials and scheme are dropped: neither changes which repository is named,
// and both differ routinely between the SSH form a clone records and the HTTPS
// form a human writes down. A port is kept unless it is the scheme's default,
// which is the only way to drop it without conflating two hosts: :8443 and :9443
// on one address can be entirely different servers, while :443 and no port on an
// https URL cannot be. An unparseable URL is returned trimmed rather than
// rejected, so it compares equal only to itself.
func normalizeRepoURL(raw string) string {
	s := strings.TrimSpace(raw)
	s = strings.TrimSuffix(s, "/")
	s = strings.TrimSuffix(s, ".git")
	s = strings.TrimSuffix(s, "/")
	if s == "" {
		return ""
	}

	// scp-form: git@host:owner/repo, which is not a URL and would parse as the
	// "git@host" scheme with an opaque body. It carries no port — git reads
	// everything after the colon as the path, so git@host:2222/o/r is a repository
	// called 2222/o/r and ssh:// is the only way to name a port.
	if !strings.Contains(s, "://") {
		if host, path, ok := strings.Cut(s, ":"); ok {
			_, host, _ = strings.Cut(host, "@") // drop any user
			return strings.ToLower(host) + "/" + strings.Trim(path, "/")
		}
		// A local path, which the tests and a bare filesystem remote both use.
		return s
	}

	u, err := url.Parse(s)
	if err != nil {
		return s
	}
	host := strings.ToLower(u.Hostname())
	if host == "" {
		// file:///path — the path is the whole identity.
		return strings.TrimRight(u.Path, "/")
	}
	if port := u.Port(); port != "" && port != defaultPort(u.Scheme) {
		host += ":" + port
	}
	return host + "/" + strings.Trim(u.Path, "/")
}

// defaultPort is the port a scheme implies, so writing it out compares equal to
// leaving it off. An unrecognised scheme has no default, which keeps whatever port
// it was given rather than guessing that it does not matter.
func defaultPort(scheme string) string {
	switch strings.ToLower(scheme) {
	case "https":
		return "443"
	case "http":
		return "80"
	case "ssh":
		return "22"
	case "git":
		return "9418"
	}
	return ""
}
package release

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// now is the clock, replaced in tests so a manifest is reproducible.
var now = time.Now

// Create publishes an immutable release manifest and pushes an annotated git
// tag. It changes no environment: what was running before is still running,
// and because the version resolves the same commit it resolves the same
// digests.
//
// Re-running for a version that already exists is safe. The existing manifest
// is compared against what this run would publish; if they agree, the release
// is left alone and only a missing git tag is repaired. If they disagree the
// version is being reused for something else, and that is refused.
func Create(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	if opts.Version == "" {
		return errors.New("a version is required")
	}
	if err := command.RequireBinaries("git"); err != nil {
		return err
	}

	cfg, err := config.Load()
	if err != nil {
		return err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
	if err != nil {
		return err
	}
	defer repo.Close()

	coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
	if err != nil {
		return err
	}
	if len(comp.Images) == 0 {
		return fmt.Errorf("%s declares no images, so there is nothing to release", coord)
	}

	g := git.Client{Runner: opts.Runner, Dir: opts.SourceDir}

	src, err := source.Inspect(ctx, g, comp.SourcePaths, opts.AllowDirty)
	if err != nil {
		return err
	}
	if len(src.Dirty) > 0 {
		fmt.Fprintf(opts.Stderr, "warning: releasing with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
	}

	// Ref defaults to HEAD, which Inspect has already checked. A different ref
	// is resolved here and checked for reachability the same way.
	commit := src.Commit
	if opts.Ref != "HEAD" {
		commit, err = g.RevParse(ctx, opts.Ref)
		if err != nil {
			return fmt.Errorf("resolve --ref %s: %w", opts.Ref, err)
		}
		pushed, err := g.IsAncestor(ctx, commit, gitops.RemoteName+"/"+src.Branch)
		if err != nil {
			return err
		}
		if !pushed {
			return &source.UnpushedCommitError{Commit: commit, Branch: gitops.RemoteName + "/" + src.Branch}
		}
	}

	reg, err := NewRegistry(opts.UserAgent)
	if err != nil {
		return err
	}

	releasesRepo := ReleasesRepo(comp.Images[0].Name)
	ref := Ref(releasesRepo, opts.Version)

	// Look before publishing. A retry after a partial run has to recognise its
	// own earlier work, and that is only possible while the existing manifest
	// is still there to compare against.
	existing, err := lookup(ctx, reg, ref)
	if err != nil {
		return err
	}

	// Registry's Resolve matches source.Resolver, so no adapter is needed.
	pins, err := source.ResolveDigests(ctx, reg, comp, commit)
	if err != nil {
		return err
	}

	basis, from, err := resolveBasis(ctx, reg, g, releasesRepo, commit, opts.Since, opts.Version)
	if err != nil {
		return err
	}

	var changes []Change
	if from != "" {
		if changes, err = Changelog(ctx, g, from, commit, comp.SourcePaths); err != nil {
			return err
		}
	}

	m := &Manifest{
		SchemaVersion: SchemaVersion,
		Component:     coord.Component,
		Version:       opts.Version,
		CreatedAt:     now().UTC().Truncate(time.Second),
		CreatedBy:     committer(),
		Source:        Source{Commit: commit, Ref: opts.Ref, Repo: repoURL},
		Images:        images(pins),
		Changes:       changes,
		ChangeBasis:   basis,
	}
	m.Notes = RenderNotes(changes, basis)

	result := Result{
		Component: m.Component,
		Version:   m.Version,
		Ref:       ref,
		Tag:       TagName(coord.Component, opts.Version),
		Manifest:  m,
	}

	switch {
	case existing == nil:
		digest, err := Push(ctx, reg, ref, m)
		if err != nil {
			return err
		}
		result.Digest, result.Created = digest, true
		fmt.Fprintf(opts.Stderr, "published %s\n", ref)

	case existing.SameRelease(m):
		// Already published, identically. Report the release that exists
		// rather than the one this run would have built.
		desc, err := reg.Resolve(ctx, ref)
		if err != nil {
			return err
		}
		result.Digest, result.Manifest = desc.Digest, existing
		fmt.Fprintf(opts.Stderr, "%s already published; nothing to do\n", ref)

	default:
		return fmt.Errorf("%s already exists and describes a different release (%s vs %s)\n"+
			"a release is immutable: pick a new version, or delete the tag in the registry if it was published in error",
			ref, shortSHA(existing.Source.Commit), shortSHA(m.Source.Commit))
	}

	// Tag after publishing. The manifest is what a release is; the tag is a
	// convenience for people reading git log, and nothing in this CLI reads it
	// — release discovery goes through the registry. So a tag that cannot be
	// pushed is reported and does not fail the command, and re-running repairs
	// it against the manifest that already exists.
	result.Tagged = tag(ctx, g, result.Tag, commit, m, opts.Stderr)

	return report(opts, result)
}

// lookup reads the manifest already published at ref, if any.
func lookup(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
	m, err := Pull(ctx, reg, ref)
	switch {
	case err == nil:
		return m, nil
	case errors.Is(err, ErrNotFound):
		return nil, nil
	case errors.Is(err, ErrNotRelease):
		// Something else holds this tag. Publishing over it would destroy
		// whatever it is.
		return nil, fmt.Errorf("%s already exists and is not a release manifest: %w", ref, err)
	default:
		return nil, err
	}
}

// resolveBasis decides what the changelog is measured against, and returns the
// commit to start from. An empty from means there is nothing to measure.
func resolveBasis(ctx context.Context, reg Registry, g git.Client, releasesRepo, commit, since, version string) (ChangeBasis, string, error) {
	if since != "" {
		from, err := g.RevParse(ctx, since)
		if err != nil {
			return ChangeBasis{}, "", fmt.Errorf("resolve --since %s: %w", since, err)
		}
		ancestor, err := g.IsAncestor(ctx, from, commit)
		if err != nil {
			return ChangeBasis{}, "", err
		}
		if !ancestor {
			return ChangeBasis{}, "", fmt.Errorf("--since %s is not an ancestor of the commit being released (%s), so there is no range between them", since, shortSHA(commit))
		}
		return ChangeBasis{Kind: BasisExplicit, Ref: since}, from, nil
	}

	prev, err := PreviousRelease(ctx, reg, g, releasesRepo, commit, version)
	if err != nil {
		return ChangeBasis{}, "", err
	}
	if prev == nil {
		// Nothing was released, so there is no prior state to diff against.
		// The window is undefined rather than large, and saying so beats
		// synthesising one: the first managed release of a component is
		// usually adoption, not birth, and --since is how an operator names
		// the point the tool cannot know.
		return ChangeBasis{Kind: BasisInitial}, "", nil
	}
	return ChangeBasis{
		Kind:    BasisRelease,
		Version: prev.Version,
		Commit:  prev.Source.Commit,
	}, prev.Source.Commit, nil
}

// TagName is the annotated tag for a release. Component-prefixed because these
// are monorepos: a bare v1.4.2 would collide the moment a second component in
// the same repository cut a release.
func TagName(component, version string) string {
	return component + "/v" + version
}

// tag creates and pushes the annotated tag, reporting whether it reached the
// remote. Every failure is a warning: the release is already published, and
// the tag is not load-bearing.
func tag(ctx context.Context, g git.Client, name, commit string, m *Manifest, stderr io.Writer) bool {
	at, exists, err := g.TagCommit(ctx, name)
	if err != nil {
		fmt.Fprintf(stderr, "warning: could not read tag %s: %v\n", name, err)
		return false
	}

	switch {
	case exists && at != commit:
		fmt.Fprintf(stderr, "warning: tag %s already points at %s, not %s; leaving it alone\n", name, shortSHA(at), shortSHA(commit))
		return false
	case !exists:
		if err := g.Tag(ctx, name, tagMessage(m), commit); err != nil {
			fmt.Fprintf(stderr, "warning: could not create tag %s: %v\n", name, err)
			return false
		}
	}

	// Pushing a tag the remote already has is a no-op, which is what makes
	// this safe to repeat.
	if err := g.Push(ctx, gitops.RemoteName, "refs/tags/"+name); err != nil {
		fmt.Fprintf(stderr, "warning: release %s is published, but its git tag could not be pushed: %v\n", m.Version, err)
		fmt.Fprintf(stderr, "         the release is valid without it; re-run to repair the tag\n")
		return false
	}
	fmt.Fprintf(stderr, "tagged %s\n", name)
	return true
}

func tagMessage(m *Manifest) string {

